import React from "react";
import { Link } from "react-router-dom";
import {
  FaShieldAlt,
  FaMicrochip,
  FaFileInvoice,
  FaUserEdit,
  FaBell,
  FaFileAlt,
  FaThLarge,
} from "react-icons/fa";

// آیتم‌های منو — ۵ تای اول به کامپوننت‌هایی که ساختیم وصل می‌شن،
// دو تای آخر («درخواست‌های ویرایش پروفایل» و «اطلاعیه‌ها») چون طرحی برایشان
// نداشتیم فقط مسیرشون آماده‌ست تا بعداً صفحه‌شون رو بسازیم.
const MENU_ITEMS = [
  { key: "brands", label: "مدیریت برند دستگاه", path: "/brands", icon: FaShieldAlt },
  { key: "device-types", label: "مدیریت نوع دستگاه", path: "/device-types", icon: FaMicrochip },
  { key: "settlements", label: "درخواست های تسویه", path: "/settlements", icon: FaFileInvoice },
  { key: "profile-edit-requests", label: "درخواست های ویرایش پروفایل", path: "/profile-edit-requests", icon: FaUserEdit },
  { key: "notifications", label: "اطلاعیه ها", path: "/notifications", icon: FaBell },
  { key: "reports", label: "گزارشات", path: "/reports", icon: FaFileAlt },
  { key: "specialties", label: "مدیریت تخصص ها", path: "/specialties", icon: FaThLarge },
];

// منوی «سایر» — ۷ دکمه که هرکدوم به مسیر مربوطه‌شون می‌رن
class SettingsMenu extends React.Component {
  render() {
    return (
      <div className="container">
        <div className=" px-3 pt-4 pb-5 d-flex flex-column gap-3">
          {MENU_ITEMS.map(({ key, label, path, icon: Icon }) => (
            <Link
              key={key}
              to={path}
              className="d-flex align-items-center justify-content-between border rounded-4 px-3 py-3 text-decoration-none"
              style={{ transition: "background-color 0.15s ease, transform 0.1s ease" }}
            >
              <Icon size={22} />
              <span className="text-black fw-semibold">{label}</span>
            </Link>
          ))}
        </div>
      </div>
    );
  }
}

export default SettingsMenu;
